import{_ as s,c as i,o as t,a2 as r}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Permissions macOS","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/permissions.md","filePath":"fr/guide/permissions.md","lastUpdated":1793163976000}'),n={name:"fr/guide/permissions.md"};function a(o,e,l,c,p,u){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="permissions-macos" tabindex="-1">Permissions macOS <a class="header-anchor" href="#permissions-macos" aria-label="Permalink to &quot;Permissions macOS&quot;">​</a></h1><p>NueZip peut demander quelques permissions macOS pour offrir la meilleure expérience. Cette page explique à quoi sert chaque permission et comment les gérer.</p><h2 id="fichiers-et-dossiers" tabindex="-1">Fichiers et dossiers <a class="header-anchor" href="#fichiers-et-dossiers" aria-label="Permalink to &quot;Fichiers et dossiers&quot;">​</a></h2><p>Pour accéder aux archives n&#39;importe où sur votre système, NueZip a besoin d&#39;une permission d&#39;accès aux fichiers.</p><p><strong>À quoi cela sert</strong> : Lecture des fichiers d&#39;archive, extraction des contenus et création de nouvelles archives.</p><p><strong>Gérer</strong> : Réglages système → <strong>Confidentialité et sécurité</strong> → <strong>Fichiers et dossiers</strong></p><p>Accordez l&#39;accès lorsque cela vous est demandé lors du premier lancement. Vous pouvez gérer ou révoquer l&#39;accès à tout moment.</p><h2 id="extension-finder" tabindex="-1">Extension Finder <a class="header-anchor" href="#extension-finder" aria-label="Permalink to &quot;Extension Finder&quot;">​</a></h2><p>NueZip inclut une extension Finder qui ajoute des options de menu contextuel au clic droit.</p><p><strong>À quoi cela sert</strong> : Faites un clic droit sur les fichiers d&#39;archive pour extraire, compresser ou ouvrir avec NueZip directement depuis Finder.</p><p><strong>Activer</strong> : Réglages système → <strong>Confidentialité et sécurité</strong> → <strong>Extensions</strong> → <strong>Extensions Finder</strong> → Activer <strong>NueZip</strong></p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>NueZip peut afficher des notifications pour les opérations de longue durée (extraction par lot, compression d&#39;archive volumineuse).</p><p><strong>À quoi cela sert</strong> : Vous alerter lorsqu&#39;une opération en arrière-plan se termine.</p><p><strong>Gérer</strong> : Réglages système → <strong>Notifications</strong> → <strong>NueZip</strong></p><h2 id="acces-au-disque-complet-optionnel" tabindex="-1">Accès au disque complet (optionnel) <a class="header-anchor" href="#acces-au-disque-complet-optionnel" aria-label="Permalink to &quot;Accès au disque complet (optionnel)&quot;">​</a></h2><p>Pour extraire des archives vers des emplacements protégés par le système, NueZip peut demander un accès au disque complet.</p><p><strong>À quoi cela sert</strong> : Écriture de fichiers extraits vers des emplacements en dehors de votre dossier utilisateur.</p><p><strong>Gérer</strong> : Réglages système → <strong>Confidentialité et sécurité</strong> → <strong>Accès au disque complet</strong></p><p>Cette permission est optionnelle et n&#39;est nécessaire que si vous travaillez avec des emplacements à l&#39;échelle du système.</p><h2 id="reinitialiser-une-permission-avec-le-terminal" tabindex="-1">Réinitialiser une permission avec le Terminal <a class="header-anchor" href="#reinitialiser-une-permission-avec-le-terminal" aria-label="Permalink to &quot;Réinitialiser une permission avec le Terminal&quot;">​</a></h2><p>Si une boîte de dialogue de permission a été ignorée ou que l&#39;état est incohérent, vous pouvez réinitialiser les invites de permission macOS à l&#39;aide de <code>tccutil</code> :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Réinitialiser les permissions pour NueZip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.nuezip</span></span></code></pre></div><p>Après l&#39;exécution de <code>tccutil</code>, redémarrez l&#39;application et déclenchez à nouveau la fonctionnalité pour être invité de nouveau.</p><h2 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h2><ul><li>Si les notifications n&#39;apparaissent pas, vérifiez que la permission <strong>Notifications</strong> est accordée.</li><li>Après modification des permissions, quittez et rouvrez toujours NueZip pour que les changements prennent effet.</li></ul><p>Pour plus d&#39;aide, consultez le <a href="./troubleshooting.html">guide de dépannage</a>.</p>`,27)])])}const h=s(n,[["render",a]]);export{m as __pageData,h as default};
